    code39: [{ key: 'height', kind: 'length' }],
    itf: [{ key: 'height', kind: 'length' }],
    ean13: [{ key: 'height', kind: 'length' }],
    upca: [{ key: 'height', kind: 'length' }],
    datamatrix: [{ key: 'height', kind: 'length' }],
